pragma solidity 0.8.36;
contract Target { uint256 public value; function f(uint256 x) external pure returns (uint256) { return x; } function f(address x) external pure returns (address) { return x; } } contract C { struct S { uint256 x; } function check(S memory s, Target target, uint256[] calldata values) external view returns (uint256) { return s.x + values.length + target.value() + target.f(1) + msg.sender.balance; } }
